import { createRoot } from 'react-dom/client';
import './index.css';
/**
 * Sample for Bar series
 */
import * as React from "react";
import { useEffect } from 'react';
import { Inject, Circular3DComponent, Circular3DSeriesCollectionDirective, Circular3DSeriesDirective, Circular3DDataLabel, Circular3DHighlight, Circular3DLegend, Circular3DTooltip, PieSeries3D } from '@syncfusion/ej2-react-charts';
import { Browser } from '@syncfusion/ej2-base';

export let data1 = [
    { 'x': 'Germany', y: 79, text: 'Germany: 79' },
    { 'x': 'China', y: 56, text: 'China: 56' },
    { 'x': 'Great Britain', y: 49, text: 'Great Britain: 49' },
    { 'x': 'Canada', y: 46, text: 'Canada: 46' },
    { 'x': 'India', y: 41, text: 'India: 41' },
    { 'x': 'Hong Kong', y: 39, text: 'Hong Kong: 39' },
    { 'x': 'Belgium', y: 34, text: 'Belgium: 34' },
    { 'x': 'United States', y: 32, text: 'United States: 32' },
    { 'x': 'Hungary', y: 30, text: 'Hungary: 30' },
    { 'x': 'Bangladesh', y: 25, text: 'Bangladesh: 25' },
];
const SAMPLE_CSS = `
    .control-fluid {
        padding: 0px !important;
    }`;
/**
 * Donut sample
 */
const PieSeries = () => {
    const onChartLoad = (args) => {
        let chart = document.getElementById('charts');
        chart.setAttribute('title', '');
    };
    const load = (args) => {
        let selectedTheme = location.hash.split('/')[1];
        selectedTheme = selectedTheme ? selectedTheme : 'Material';
        args.chart.theme = (selectedTheme.charAt(0).toUpperCase() + selectedTheme.slice(1)).replace(/-dark/i, "Dark").replace(/contrast/i, 'Contrast');
    };
    return (<div className='control-pane'>
        <style>{SAMPLE_CSS}</style>
        <div className='control-section'>
            <div>
                <Circular3DComponent id='charts' style={{ textAlign: "center" }} legendSettings={{ visible: false }} highlightMode='Point' tilt={-30} enableRotation={true} load={load.bind(this)} title='Berlin 2023 Special Olympics Gold Medals' loaded={onChartLoad.bind(this)} tooltip={{ enable: true, format: "<b>${point.x}</b><br> Gold Medals: <b>${point.y}</b>", header: "" }}>
                    <Inject services={[PieSeries3D, Circular3DDataLabel, Circular3DLegend, Circular3DTooltip, Circular3DHighlight]}/>
                    <Circular3DSeriesCollectionDirective>
                        <Circular3DSeriesDirective dataSource={data1} xName='x' yName='y' explode={true} innerRadius='0%' radius={Browser.isDevice ? '45%' : '80%'} dataLabel={{ visible: true, position: 'Outside', name: 'text', font: { fontWeight: '600' }, connectorStyle: { length: Browser.isDevice ? '20px' : '40px' } }}>
                        </Circular3DSeriesDirective>
                    </Circular3DSeriesCollectionDirective>
                </Circular3DComponent>
            </div>
        </div>
    </div>);
};
export default PieSeries;

const root = createRoot(document.getElementById('sample'));
root.render(<PieSeries />);
